const mongoose = require('mongoose')

// Each question generated by Gemini, plus the user's answer and its evaluation
const questionSchema = new mongoose.Schema(
  {
    questionText: {
      type: String,
      required: true,
    },
    type: {
      type: String,
      enum: ['technical', 'coding', 'hr', 'behavioral'],
      default: 'technical',
    },
    userAnswer: {
      type: String,
      default: '',
    },
    score: {
      type: Number, // out of 10, set during evaluation
      default: null,
    },
    feedback: {
      type: String,
      default: '',
    },
    idealAnswer: {
      type: String,
      default: '',
    },
  },
  { _id: false }
)

const interviewSchema = new mongoose.Schema(
  {
    user: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: true,
      index: true,
    },
    topic: {
      type: String,
      required: true,
      trim: true,
    },
    type: {
      type: String,
      enum: ['technical', 'coding', 'hr', 'behavioral'],
      default: 'technical',
    },
    difficulty: {
      type: String,
      enum: ['easy', 'medium', 'hard'],
      default: 'medium',
    },
    questions: {
      type: [questionSchema],
      default: [],
    },
    status: {
      type: String,
      enum: ['in-progress', 'completed'],
      default: 'in-progress',
    },
    score: {
      type: Number, // overall percentage, set after finalization
      default: null,
    },
    overallRating: {
      type: String,
      default: '',
    },
    feedback: {
      type: String, // overall summary feedback
      default: '',
    },
    strengths: {
      type: [String],
      default: [],
    },
    weakAreas: {
      type: [String],
      default: [],
    },
  },
  { timestamps: true } // adds createdAt and updatedAt automatically
)

module.exports = mongoose.model('Interview', interviewSchema)